package com.rsd.middle.external;

import com.rsd.middle.common.BizException;
import com.rsd.middle.credit.CreditApplicationOrder;
import com.rsd.middle.credit.CreditApplicationRepository;
import com.rsd.middle.credit.CreditService;
import com.rsd.middle.drawdown.DrawdownOrder;
import com.rsd.middle.drawdown.DrawdownOrderRepository;
import com.rsd.middle.drawdown.DrawdownService;
import com.rsd.middle.repay.RepaymentOrder;
import com.rsd.middle.repay.RepaymentOrderRepository;
import com.rsd.middle.repay.RepaymentService;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;
import java.math.BigDecimal;
import java.util.Map;

/**
 * 外部结果回调接收（模拟服务 → 中台）：付款、扣款、授信审批。
 * 幂等由各业务服务保证：终态业务单收到重复回调直接确认（DUPLICATE_CALLBACK 不改变状态）。
 * 回调成功只代表外部环节完成；提款是否成功以中台入账状态为准，授信是否生效以中台账本为准。
 */
@RestController
@RequestMapping("/middle/api/v1/callbacks")
public class ExternalResultController {

    private static final Logger log = LoggerFactory.getLogger(ExternalResultController.class);

    private final DrawdownOrderRepository drawdownRepo;
    private final RepaymentOrderRepository repayRepo;
    private final CreditApplicationRepository creditRepo;
    private final DrawdownService drawdownService;
    private final RepaymentService repaymentService;
    private final CreditService creditService;

    public ExternalResultController(DrawdownOrderRepository drawdownRepo, RepaymentOrderRepository repayRepo,
                                    CreditApplicationRepository creditRepo, DrawdownService drawdownService,
                                    RepaymentService repaymentService, CreditService creditService) {
        this.drawdownRepo = drawdownRepo;
        this.repayRepo = repayRepo;
        this.creditRepo = creditRepo;
        this.drawdownService = drawdownService;
        this.repaymentService = repaymentService;
        this.creditService = creditService;
    }

    public record ExternalResult(String type, String extSerialNo, String bizOrderNo, String result,
                                 BigDecimal approvedLimit, String finishedAt) {
    }

    @PostMapping("/external-result")
    public Map<String, Object> onExternalResult(@RequestBody ExternalResult callback) {
        log.info("收到外部结果回调: {}", callback);
        try {
            switch (callback.type()) {
                case "PAYMENT" -> {
                    DrawdownOrder order = drawdownRepo.findById(callback.bizOrderNo()).orElse(null);
                    if (order != null && callback.extSerialNo().equals(order.getExtSerialNo())) {
                        drawdownService.onPaymentResult(order, callback.result());
                    }
                }
                case "DEDUCTION" -> {
                    RepaymentOrder order = repayRepo.findById(callback.bizOrderNo()).orElse(null);
                    if (order != null && callback.extSerialNo().equals(order.getExtSerialNo())) {
                        repaymentService.onDeductionResult(order, callback.result());
                    }
                }
                case "APPROVAL" -> {
                    CreditApplicationOrder order = creditRepo.findById(callback.bizOrderNo()).orElse(null);
                    if (order != null && callback.extSerialNo().equals(order.getApprovalExtSerialNo())) {
                        creditService.onApprovalResult(order, callback.result(), callback.approvedLimit());
                    }
                }
                default -> log.warn("未知回调类型: {}", callback.type());
            }
        } catch (BizException e) {
            if (e.code != BizException.Code.DUPLICATE_CALLBACK) {
                throw e;
            }
        }
        return Map.of("received", true);
    }
}

package com.rsd.middle.repay;

import jakarta.persistence.Entity;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDateTime;

/** 还款订单：扣款执行与入账状态。分配明细来自 Fineract 还款交易（本金/利息/费用），中台保存分配结果用于额度恢复与核对。 */
@Entity
@Table(name = "repayment_order")
public class RepaymentOrder {

    public enum Status { PROCESSING, SUCCESS, FAILED }

    public enum Type { DUE, EARLY_PRINCIPAL, EARLY_SETTLE }

    public enum DeductionStatus { TO_SUBMIT, PROCESSING, SUCCESS, FAILED, RESULT_UNCONFIRMED }

    @Id
    private String bizOrderNo;
    private String loanAccountNo;
    private String creditId;            // 借据所属授信（来自提款业务单关联）
    private String payerAccount;
    private Type type;
    private BigDecimal amount;

    private Status status;
    private DeductionStatus deductionStatus;
    private String extSerialNo;
    private String fineractTransactionId;
    private BigDecimal principalPortion;   // 分配明细：本金部分（恢复额度依据）
    private BigDecimal interestPortion;
    private BigDecimal feePortion;
    private LocalDateTime createdAt;
    private LocalDateTime updatedAt;

    public boolean terminal() {
        return status == Status.SUCCESS || status == Status.FAILED;
    }

    public String getBizOrderNo() { return bizOrderNo; }
    public void setBizOrderNo(String bizOrderNo) { this.bizOrderNo = bizOrderNo; }
    public String getLoanAccountNo() { return loanAccountNo; }
    public void setLoanAccountNo(String loanAccountNo) { this.loanAccountNo = loanAccountNo; }
    public String getCreditId() { return creditId; }
    public void setCreditId(String creditId) { this.creditId = creditId; }
    public String getPayerAccount() { return payerAccount; }
    public void setPayerAccount(String payerAccount) { this.payerAccount = payerAccount; }
    public Type getType() { return type; }
    public void setType(Type type) { this.type = type; }
    public BigDecimal getAmount() { return amount; }
    public void setAmount(BigDecimal amount) { this.amount = amount; }
    public Status getStatus() { return status; }
    public void setStatus(Status status) { this.status = status; }
    public DeductionStatus getDeductionStatus() { return deductionStatus; }
    public void setDeductionStatus(DeductionStatus deductionStatus) { this.deductionStatus = deductionStatus; }
    public String getExtSerialNo() { return extSerialNo; }
    public void setExtSerialNo(String extSerialNo) { this.extSerialNo = extSerialNo; }
    public String getFineractTransactionId() { return fineractTransactionId; }
    public void setFineractTransactionId(String fineractTransactionId) { this.fineractTransactionId = fineractTransactionId; }
    public BigDecimal getPrincipalPortion() { return principalPortion; }
    public void setPrincipalPortion(BigDecimal principalPortion) { this.principalPortion = principalPortion; }
    public BigDecimal getInterestPortion() { return interestPortion; }
    public void setInterestPortion(BigDecimal interestPortion) { this.interestPortion = interestPortion; }
    public BigDecimal getFeePortion() { return feePortion; }
    public void setFeePortion(BigDecimal feePortion) { this.feePortion = feePortion; }
    public LocalDateTime getCreatedAt() { return createdAt; }
    public void setCreatedAt(LocalDateTime createdAt) { this.createdAt = createdAt; }
    public LocalDateTime getUpdatedAt() { return updatedAt; }
    public void setUpdatedAt(LocalDateTime updatedAt) { this.updatedAt = updatedAt; }
}

package com.rsd.middle.repay;

import com.rsd.middle.credit.LimitService;
import com.rsd.middle.credit.ProductConfig;
import com.rsd.middle.credit.ProductConfigRepository;
import com.rsd.middle.common.BizException;
import com.rsd.middle.common.Ids;
import com.rsd.middle.drawdown.DrawdownOrder;
import com.rsd.middle.drawdown.DrawdownOrderRepository;
import com.rsd.middle.external.SimulatorClient;
import com.rsd.middle.fineract.FineractClient;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;
import java.util.Map;

/**
 * 还款编排：订单 → 模拟扣款 → 确认到账 → Fineract 还款入账 → 读取分配明细 → 按本金逐层恢复占用。
 * 规则（docs/三系统边界设计.md §6）：归还利息、费用不恢复本金授信额度；
 * 分配顺序由 Fineract 产品策略决定，中台只保存分配结果，不在多个系统重复判断分配。
 */
@Service
public class RepaymentService {

    private static final Logger log = LoggerFactory.getLogger(RepaymentService.class);

    private final RepaymentOrderRepository orderRepo;
    private final DrawdownOrderRepository drawdownRepo;
    private final LimitService limitService;
    private final ProductConfigRepository productRepo;
    private final FineractClient fineract;
    private final SimulatorClient simulator;

    public RepaymentService(RepaymentOrderRepository orderRepo, DrawdownOrderRepository drawdownRepo,
                            LimitService limitService, ProductConfigRepository productRepo,
                            FineractClient fineract, SimulatorClient simulator) {
        this.orderRepo = orderRepo;
        this.drawdownRepo = drawdownRepo;
        this.limitService = limitService;
        this.productRepo = productRepo;
        this.fineract = fineract;
        this.simulator = simulator;
    }

    /** 提前结清/部分还本试算：透传 Fineract calculatePrepayment 结果（金额构成见源码核查报告 §1）。 */
    public Map<String, Object> prepaymentQuote(String loanAccountNo, String type, BigDecimal amount) {
        requireLoan(loanAccountNo);
        Map<String, Object> trial = fineract.calculatePrepayment(loanAccountNo, Ids.now().toLocalDate().toString());
        return Map.of("loanAccountNo", loanAccountNo, "type", type,
                "amount", amount == null ? trial.get("amount") : amount, "trial", trial);
    }

    @Transactional
    public RepaymentOrder apply(String loanAccountNo, String payerAccount, String type, BigDecimal amount) {
        requireLoan(loanAccountNo);
        RepaymentOrder order = new RepaymentOrder();
        order.setBizOrderNo(Ids.next("RP-"));
        order.setLoanAccountNo(loanAccountNo);
        order.setCreditId(creditOfLoan(loanAccountNo));
        order.setPayerAccount(payerAccount);
        order.setType(RepaymentOrder.Type.valueOf(type));
        order.setAmount(amount);
        order.setStatus(RepaymentOrder.Status.PROCESSING);
        order.setDeductionStatus(RepaymentOrder.DeductionStatus.TO_SUBMIT);
        order.setCreatedAt(Ids.now());
        order.setUpdatedAt(Ids.now());
        orderRepo.save(order);
        submitDeduction(order);
        return order;
    }

    public void submitDeduction(RepaymentOrder order) {
        try {
            SimulatorClient.PaymentSubmission sub = simulator.submitDeduction(
                    order.getBizOrderNo(), order.getPayerAccount(), order.getAmount());
            order.setExtSerialNo(sub.extSerialNo());
            order.setUpdatedAt(Ids.now());
            switch (sub.status()) {
                case "SUCCESS" -> onDeductionResult(order, "SUCCESS");
                case "REJECTED" -> onDeductionResult(order, "FAILED");
                default -> order.setDeductionStatus(RepaymentOrder.DeductionStatus.PROCESSING);
            }
        } catch (Exception e) {
            log.warn("扣款提交失败，等待补偿重试: {} {}", order.getBizOrderNo(), e.getMessage());
        }
    }

    /** 扣款结果（回调与查单共用）。幂等：终态订单收到重复结果直接忽略。 */
    @Transactional
    public void onDeductionResult(RepaymentOrder order, String result) {
        if (order.terminal()) {
            return;
        }
        order.setUpdatedAt(Ids.now());
        if ("SUCCESS".equals(result)) {
            if (order.getDeductionStatus() == RepaymentOrder.DeductionStatus.SUCCESS) {
                return;
            }
            order.setDeductionStatus(RepaymentOrder.DeductionStatus.SUCCESS);
            book(order);
        } else {
            if (order.getDeductionStatus() == RepaymentOrder.DeductionStatus.FAILED) {
                return;
            }
            order.setDeductionStatus(RepaymentOrder.DeductionStatus.FAILED);
            order.setStatus(RepaymentOrder.Status.FAILED);
        }
    }

    /** 入账：Fineract 还款交易 + 分配明细 + 本金恢复额度。分配失败不阻断入账记录，转补偿重读。 */
    @Transactional
    public void book(RepaymentOrder order) {
        if (order.getStatus() == RepaymentOrder.Status.SUCCESS) {
            return;
        }
        try {
            String transactionId = fineract.repayLoan(order.getLoanAccountNo(), order.getAmount());
            FineractClient.RepaymentAllocation allocation =
                    fineract.getRepaymentAllocation(order.getLoanAccountNo(), transactionId);
            order.setFineractTransactionId(allocation.transactionId());
            order.setPrincipalPortion(allocation.principalPortion());
            order.setInterestPortion(allocation.interestPortion());
            order.setFeePortion(allocation.feePortion());
            order.setStatus(RepaymentOrder.Status.SUCCESS);
            order.setUpdatedAt(Ids.now());
            // 只有本金部分逐层恢复授信占用；利息、费用不恢复（担保层按覆盖比例折算）
            DrawdownOrder drawdown = drawdownRepo.findByLoanAccountNo(order.getLoanAccountNo()).orElse(null);
            String productId = drawdown == null ? null : drawdown.getProductId();
            boolean requiresGuarantee = productId == null || productRepo.findById(productId)
                    .map(ProductConfig::isRequiresGuarantee).orElse(false);
            limitService.restoreByPrincipal(order.getCreditId(), order.getBizOrderNo(),
                    order.getLoanAccountNo(), productId, requiresGuarantee, allocation.principalPortion());
        } catch (Exception e) {
            log.warn("还款入账失败，等待补偿重试: {} {}", order.getBizOrderNo(), e.getMessage());
            // 入账失败时订单保持 PROCESSING，补偿任务基于"扣款已成功"重试入账；
            // Fineract 侧重复还款由 adapter 先查交易是否已存在来防重。
        }
    }

    /** 查单收敛（补偿任务用）。 */
    @Transactional
    public void queryAndSettle(RepaymentOrder order) {
        SimulatorClient.ExternalStatus status = simulator.query("DEDUCTION", order.getExtSerialNo());
        if ("SUCCESS".equals(status.status()) || "FAILED".equals(status.status())) {
            onDeductionResult(order, status.status());
        } else if ("RESULT_UNCONFIRMED".equals(status.status())) {
            order.setDeductionStatus(RepaymentOrder.DeductionStatus.RESULT_UNCONFIRMED);
        }
    }

    public Map<String, Object> detail(String bizOrderNo) {
        RepaymentOrder order = orderRepo.findById(bizOrderNo).orElseThrow();
        return Map.of("bizOrderNo", order.getBizOrderNo(), "status", order.getStatus().name(),
                "amount", order.getAmount(),
                "allocation", Map.of("principalPortion", order.getPrincipalPortion() == null ? 0 : order.getPrincipalPortion(),
                        "interestPortion", order.getInterestPortion() == null ? 0 : order.getInterestPortion(),
                        "feePortion", order.getFeePortion() == null ? 0 : order.getFeePortion()));
    }

    private void requireLoan(String loanAccountNo) {
        if (drawdownRepo.findByLoanAccountNo(loanAccountNo).isEmpty()) {
            throw new BizException(BizException.Code.LOAN_NOT_FOUND);
        }
    }

    private String creditOfLoan(String loanAccountNo) {
        return drawdownRepo.findByLoanAccountNo(loanAccountNo)
                .map(DrawdownOrder::getCreditId)
                .orElseThrow(() -> new BizException(BizException.Code.LOAN_NOT_FOUND));
    }
}

