package com.rsd.middle.compensation;

import com.rsd.middle.credit.CreditApplicationOrder;
import com.rsd.middle.credit.CreditApplicationRepository;
import com.rsd.middle.credit.CreditService;
import com.rsd.middle.drawdown.DrawdownOrder;
import com.rsd.middle.drawdown.DrawdownOrderRepository;
import com.rsd.middle.drawdown.DrawdownService;
import com.rsd.middle.repay.RepaymentOrder;
import com.rsd.middle.repay.RepaymentOrderRepository;
import com.rsd.middle.repay.RepaymentService;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Component;
import java.time.Duration;
import java.time.LocalDateTime;
import java.util.List;

/**
 * 查单与补偿任务（不引入消息中间件，用定时任务收敛异步结果，见边界设计原则 6）：
 * 1. 提交失败 → 重新提交（模拟服务按 bizOrderNo 幂等）；
 * 2. 受理中超时未收到回调 → 主动查单（"回调未送达，通过查单取得结果"场景）；
 * 3. 提款入账未完成（TO_BOOK / RETRY_NEEDED）→ 重试入账，先查借据是否已 ACTIVE 防重复放款；
 * 4. 授信审批受理超时 → 查审批结论。
 */
@Component
public class CompensationTask {

    private static final Logger log = LoggerFactory.getLogger(CompensationTask.class);

    private final DrawdownOrderRepository drawdownRepo;
    private final RepaymentOrderRepository repayRepo;
    private final CreditApplicationRepository creditRepo;
    private final DrawdownService drawdownService;
    private final RepaymentService repaymentService;
    private final CreditService creditService;
    private final long paymentQueryTimeoutSeconds;
    private final int bookingRetryMax;

    public CompensationTask(DrawdownOrderRepository drawdownRepo, RepaymentOrderRepository repayRepo,
                            CreditApplicationRepository creditRepo, DrawdownService drawdownService,
                            RepaymentService repaymentService, CreditService creditService,
                            @Value("${compensation.payment-query-timeout-seconds:60}") long paymentQueryTimeoutSeconds,
                            @Value("${compensation.booking-retry-max:5}") int bookingRetryMax) {
        this.drawdownRepo = drawdownRepo;
        this.repayRepo = repayRepo;
        this.creditRepo = creditRepo;
        this.drawdownService = drawdownService;
        this.repaymentService = repaymentService;
        this.creditService = creditService;
        this.paymentQueryTimeoutSeconds = paymentQueryTimeoutSeconds;
        this.bookingRetryMax = bookingRetryMax;
    }

    @Scheduled(fixedDelayString = "${compensation.poll-interval-ms:15000}")
    public void compensate() {
        // 提款：提交失败重试
        drawdownRepo.findByPaymentStatus(DrawdownOrder.PaymentStatus.TO_SUBMIT)
                .forEach(drawdownService::submitPayment);
        // 提款：受理超时主动查单
        LocalDateTime deadline = LocalDateTime.now().minus(Duration.ofSeconds(paymentQueryTimeoutSeconds));
        List<DrawdownOrder> pendingPayments = drawdownRepo.findByPaymentStatus(DrawdownOrder.PaymentStatus.PROCESSING);
        for (DrawdownOrder order : pendingPayments) {
            if (order.getUpdatedAt() != null && order.getUpdatedAt().isBefore(deadline)) {
                log.info("提款付款超时，主动查单: {}", order.getBizOrderNo());
                drawdownService.queryAndSettle(order);
            }
        }
        // 提款：入账未完成 → 重试（含"外部已成功、中台未入账"的可恢复状态）
        for (DrawdownOrder order : drawdownRepo.findByBookingStatus(DrawdownOrder.BookingStatus.TO_BOOK)) {
            drawdownService.book(order);
        }
        for (DrawdownOrder order : drawdownRepo.findByBookingStatus(DrawdownOrder.BookingStatus.RETRY_NEEDED)) {
            if (order.getBookingRetryCount() != null && order.getBookingRetryCount() < bookingRetryMax) {
                drawdownService.book(order);
            }
        }
        // 还款：同样的三条补偿线
        repayRepo.findByDeductionStatus(RepaymentOrder.DeductionStatus.TO_SUBMIT)
                .forEach(repaymentService::submitDeduction);
        for (RepaymentOrder order : repayRepo.findByDeductionStatus(RepaymentOrder.DeductionStatus.PROCESSING)) {
            if (order.getUpdatedAt() != null && order.getUpdatedAt().isBefore(deadline)) {
                log.info("还款扣款超时，主动查单: {}", order.getBizOrderNo());
                repaymentService.queryAndSettle(order);
            }
        }
        // 扣款成功但入账未完成的还款订单（PROCESSING 且扣款已 SUCCESS）
        repayRepo.findByDeductionStatus(RepaymentOrder.DeductionStatus.SUCCESS).stream()
                .filter(order -> order.getStatus() == RepaymentOrder.Status.PROCESSING)
                .forEach(repaymentService::book);
        // 授信审批：未拿到流水号的重试提交；受理超时的查审批结论
        creditRepo.findByStatus(CreditApplicationOrder.Status.PROCESSING).forEach(order -> {
            if (order.getApprovalExtSerialNo() == null) {
                creditService.submitApproval(order);
            } else if (order.getUpdatedAt() != null && order.getUpdatedAt().isBefore(deadline)) {
                log.info("授信审批超时，主动查单: {}", order.getBizOrderNo());
                creditService.queryAndSettle(order);
            }
        });
    }
}

