package com.rsd.middle.external;

import com.rsd.middle.common.BizException;
import org.springframework.boot.context.properties.EnableConfigurationProperties;
import org.springframework.stereotype.Component;
import org.springframework.web.client.RestClient;
import java.math.BigDecimal;
import java.util.Map;

/**
 * 外部模拟服务适配：付款/扣款提交与查单。
 * 幂等约定：同一 bizOrderNo 重复提交返回同一流水号（模拟服务保证），补偿任务重试不产生新指令。
 */
@Component
@EnableConfigurationProperties(SimulatorProperties.class)
public class SimulatorClient {

    private final SimulatorProperties props;
    private final RestClient http;

    public SimulatorClient(SimulatorProperties props) {
        this.props = props;
        this.http = RestClient.builder().baseUrl(props.baseUrl()).build();
    }

    @SuppressWarnings("unchecked")
    public PaymentSubmission submitPayment(String bizOrderNo, String payeeName, String payeeAccount, BigDecimal amount) {
        return http.post().uri("/sim/api/v1/payments")
                .body(Map.of("bizOrderNo", bizOrderNo, "payeeName", payeeName,
                        "payeeAccount", payeeAccount, "amount", amount))
                .retrieve().body(PaymentSubmission.class);
    }

    @SuppressWarnings("unchecked")
    public PaymentSubmission submitDeduction(String bizOrderNo, String payerAccount, BigDecimal amount) {
        return http.post().uri("/sim/api/v1/deductions")
                .body(Map.of("bizOrderNo", bizOrderNo, "payerAccount", payerAccount, "amount", amount))
                .retrieve().body(PaymentSubmission.class);
    }

    /** 查单：模拟服务返回外部交易真实终态（回调未送达时也查得到）。 */
    @SuppressWarnings("unchecked")
    public ExternalStatus query(String kind, String extSerialNo) {
        String path = "PAYMENT".equals(kind) ? "/sim/api/v1/payments/" : "DEDUCTION".equals(kind) ? "/sim/api/v1/deductions/" : "/sim/api/v1/approvals/";
        try {
            return http.get().uri(path + extSerialNo).retrieve().body(ExternalStatus.class);
        } catch (Exception e) {
            throw new BizException(BizException.Code.SIMULATOR_ERROR);
        }
    }

    /** 提交授信审批（幂等按 bizOrderNo）。 */
    @SuppressWarnings("unchecked")
    public PaymentSubmission submitApproval(String bizOrderNo, String customerName, BigDecimal requestedLimit) {
        return http.post().uri("/sim/api/v1/approvals")
                .body(Map.of("bizOrderNo", bizOrderNo, "customerName", customerName, "requestedLimit", requestedLimit))
                .retrieve().body(PaymentSubmission.class);
    }

    public record PaymentSubmission(String extSerialNo, String status) {
    }

    /** 审批查单：status 为受理状态，result 为审批结论（APPROVED/REJECTED），approvedLimit 为批准额度。 */
    public record ExternalStatus(String extSerialNo, String status, String result,
                                 BigDecimal approvedLimit, String finishedAt) {
    }
}

