/**
 * 多层额度台账服务：总授信、产品子额度、集团限额、担保覆盖四层，可用额度取各层余量最小值。
 * 规则（docs/接口契约-阶段3.md §1）：
 * - 提款受理逐层预占；入账后逐层转实占；付款失败逐层释放；本金还款逐层恢复。
 * - 冻结：available 为 0，但恢复（占用减少）不受影响。
 * - restricted（降额占用超上限）：总授信层余量下限 0，只限制新增提款。
 * - 利息、费用不恢复任何层的占用。
 */
@Service
public class LimitService {

    private final CreditLimitRepository limitRepo;
    private final LimitRecordRepository recordRepo;
    private final ProductSubLimitRepository subLimitRepo;
    private final GroupLimitRepository groupRepo;
    private final GroupMemberRepository groupMemberRepo;
    private final GuaranteeCoverageRepository coverageRepo;

    public LimitService(CreditLimitRepository limitRepo, LimitRecordRepository recordRepo,
                        ProductSubLimitRepository subLimitRepo, GroupLimitRepository groupRepo,
                        GroupMemberRepository groupMemberRepo, GuaranteeCoverageRepository coverageRepo) {
        this.limitRepo = limitRepo;
        this.recordRepo = recordRepo;
        this.subLimitRepo = subLimitRepo;
        this.groupRepo = groupRepo;
        this.groupMemberRepo = groupMemberRepo;
        this.coverageRepo = coverageRepo;
    }

    public CreditLimit get(String creditId) {
        return limitRepo.findById(creditId)
                .orElseThrow(() -> new EntityNotFoundException("授信不存在: " + creditId));
    }

    /** 各层余量视图（不判定资格，只算数）。 */
    public Map<String, Object> layerView(String creditId, String productId) {
        CreditLimit limit = get(creditId);
        Map<String, Object> layers = new LinkedHashMap<>();
        layers.put("TOTAL", Map.of("limit", limit.getTotalLimit(),
                "occupied", limit.getOccupied(), "preOccupied", limit.getPreOccupied(),
                "remaining", limit.totalRemaining()));
        findSubLimit(creditId, productId).ifPresent(sub ->
                layers.put("PRODUCT", Map.of("productId", productId, "limit", sub.getSubLimit(),
                        "occupied", sub.getOccupied(), "preOccupied", sub.getPreOccupied(),
                        "remaining", sub.remaining())));
        findGroupOf(creditId).ifPresent(group ->
                layers.put("GROUP", Map.of("groupNo", group.getGroupNo(), "limit", group.getGroupLimit(),
                        "occupied", group.getOccupied(), "preOccupied", group.getPreOccupied(),
                        "remaining", group.remaining())));
        findCoverage(creditId).ifPresent(coverage ->
                layers.put("GUARANTEE", Map.of("orgName", coverage.getOrgName(),
                        "coverageLimit", coverage.getCoverageLimit(),
                        "coverageRatio", coverage.getCoverageRatio(),
                        "occupied", coverage.getOccupied(), "preOccupied", coverage.getPreOccupied(),
                        "remaining", coverage.remaining(), "supportable", coverage.supportable())));
        return layers;
    }

    /** 新增提款的最终可用额度：冻结为 0；否则各层余量取最小值。 */
    public BigDecimal availableForDrawdown(String creditId, String productId, boolean productRequiresGuarantee) {
        CreditLimit limit = get(creditId);
        if (limit.isFrozen()) {
            return BigDecimal.ZERO;
        }
        BigDecimal available = limit.totalRemaining();
        Optional<ProductSubLimit> sub = findSubLimit(creditId, productId);
        if (sub.isPresent()) {
            available = available.min(sub.get().remaining());
        }
        Optional<GroupLimit> group = findGroupOf(creditId);
        if (group.isPresent()) {
            available = available.min(group.get().remaining());
        }
        if (productRequiresGuarantee) {
            Optional<GuaranteeCoverage> coverage = findCoverage(creditId);
            if (coverage.isEmpty()) {
                return BigDecimal.ZERO; // 担保要求=开 但无有效担保覆盖，不可借
            }
            available = available.min(coverage.get().supportable());
        }
        return available.max(BigDecimal.ZERO);
    }

